        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue

            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            r, c = r1, c1
            while True:
                if out[r][c] == bg:
                    out[r][c] = 1
                if (r, c) in sixes:
                    triggers.add((r, c, sr * sc))
                if (r, c) == (r2, c2):
                    break
                r += sr
                c += sc

    # Each 6 on a joined diagonal draws a full perpendicular 6 diagonal.
    for r, c, joined_slope in triggers:
        perpendicular_slope = -joined_slope
        for step in range(-max(h, w), max(h, w) + 1):
            rr = r + step
            cc = c + perpendicular_slope * step
            if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                out[rr][cc] = 6

    return out
